    # Initial placement of knights
    knights = []
    for i in range(n):
        knights.append((i, 0))

    # Function to count attacks on a cell
    def count_attacks(x, y, knights):
        count = 0
        for kx, ky in knights:
            if (abs(x - kx) == 2 and abs(y - ky) == 1) or (abs(x - kx) == 1 and abs(y - ky) == 2):
                count += 1
        return count

    # Process to add new knights
    while True:
        new_knights = []
        for x in range(-10**9, 10**9 + 1):
            for y in range(-10**9, 10**9 + 1):
                if (x, y) not in knights and count_attacks(x, y, knights) >= 4:
                    new_knights.append((x, y))
        if not new_knights:
            break
        knights.extend(new_knights)

